<?php $ch = curl_init("https://goldpay.odofast.in/backend/api/auth/login.php"); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"); curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(["mobile"=>"9999999999", "password"=>"123456"])); curl_setopt($ch, CURLOPT_HTTPHEADER, ["Content-Type: application/json", "Accept: application/json"]); echo curl_exec($ch); if(curl_errno($ch)) echo curl_error($ch);
